/** Volume handling. The IFrame API accepts 0-100 and silently ignores anything else. */

export const MIN_VOLUME = 0;
export const MAX_VOLUME = 100;

/**
 * Bring any number into the range the player accepts.
 * Sliders, stored settings and keyboard steps all funnel through here, so a bad value
 * can never reach the player and leave one slot mysteriously silent.
 */
export function clampVolume(value: number): number {
  if (!Number.isFinite(value)) return MAX_VOLUME;
  return Math.min(MAX_VOLUME, Math.max(MIN_VOLUME, Math.round(value)));
}
