/**
 * The picker: choose a video out of the operator's own YouTube instead of pasting an address.
 *
 * Typing a video id on a phone is the part of this app that was always tedious. Everything here
 * exists to replace that with tapping. It is strictly additive — the panel starts hidden, and
 * the two players never learn that it exists beyond the one callback that hands them a video id.
 *
 * Rows are built with `textContent`, never `innerHTML`. Titles come from other people's
 * channels, so they are untrusted text that must never be parsed as markup.
 */

import type { GoogleAuth } from '../auth/google.js';
import { type Layout, MAX_SLOTS } from '../core/session.js';
import {
  type LibraryItem,
  YouTubeApiError,
  fetchChannelVideos,
  fetchLikedVideos,
  fetchPlaylistItems,
  fetchPlaylists,
  fetchSubscriptions,
  searchVideos,
} from '../youtube/library.js';
import { must } from './dom.js';

/**
 * Where a tapped video goes. The pair screen names its two slots; the wall has twenty, far too
 * many to name on every row, so there it goes to whichever slot is currently chosen.
 */
export type PickTarget = 'video' | 'music' | 'next';

export interface LibraryCallbacks {
  readonly onPick: (videoId: string, target: PickTarget) => void;
  readonly onFillAll: (videoIds: readonly string[]) => void;
  readonly layout: () => Layout;
}

type Tab = 'search' | 'playlists' | 'subscriptions' | 'liked';

const TAB_TITLE: Record<Tab, string> = {
  search: '検索',
  playlists: '再生リスト',
  subscriptions: '登録チャンネル',
  liked: '高評価した動画',
};

const EMPTY_NOTE: Record<Tab, string> = {
  search: '探したい言葉を入れて「探す」を押す。',
  playlists: '再生リストがありません。',
  subscriptions: '登録しているチャンネルがありません。',
  liked: '高評価した動画がありません。',
};

function isTab(value: string | undefined): value is Tab {
  return (
    value === 'search' || value === 'playlists' || value === 'subscriptions' || value === 'liked'
  );
}

/** Where the panel currently is. A drill-down keeps the tab it came from, for the back button. */
type View =
  | { readonly kind: 'tab'; readonly tab: Tab }
  | { readonly kind: 'playlist'; readonly tab: Tab; readonly item: LibraryItem }
  | { readonly kind: 'channel'; readonly tab: Tab; readonly item: LibraryItem }
  | { readonly kind: 'search'; readonly tab: Tab; readonly query: string };

function describeView(view: View): string {
  if (view.kind === 'tab') return TAB_TITLE[view.tab];
  if (view.kind === 'search') return `「${view.query}」`;
  return view.item.title;
}

function describeEmpty(view: View): string {
  if (view.kind === 'tab') return EMPTY_NOTE[view.tab];
  if (view.kind === 'search') return '見つかりませんでした。別の言葉で探してください。';
  return '中身がありません。';
}

function describeFailure(error: unknown): string {
  if (error instanceof YouTubeApiError) {
    // A spent search budget and a refused token are both 403. Only the reason tells them apart,
    // and sending someone to sign in again when the answer is "tomorrow" wastes their evening.
    if (error.reason === 'quotaExceeded' || error.reason === 'rateLimitExceeded') {
      return '今日の検索の上限に達しました。日付が変わると戻ります。';
    }
    if (error.status === 401 || error.status === 403) {
      return 'YouTube に断られました。ログインし直してください。';
    }
    return `YouTube が応じません (${error.status})。`;
  }
  return '一覧を取れませんでした。通信を確かめてください。';
}

export class LibraryPanel {
  readonly #panel: HTMLElement;
  readonly #title: HTMLElement;
  readonly #back: HTMLButtonElement;
  readonly #note: HTMLElement;
  readonly #list: HTMLElement;
  readonly #tabs: readonly HTMLButtonElement[];
  readonly #searchRow: HTMLElement;
  readonly #searchInput: HTMLInputElement;
  readonly #auth: GoogleAuth;
  readonly #callbacks: LibraryCallbacks;

  #view: View = { kind: 'tab', tab: 'playlists' };
  /** Guards against a slow response painting over a list the operator has already left. */
  #requestId = 0;

  constructor(auth: GoogleAuth, callbacks: LibraryCallbacks) {
    this.#auth = auth;
    this.#callbacks = callbacks;

    this.#panel = must<HTMLElement>(document, '#library');
    this.#title = must<HTMLElement>(document, '#libraryTitle');
    this.#back = must<HTMLButtonElement>(document, '#libraryBack');
    this.#note = must<HTMLElement>(document, '#libraryNote');
    this.#list = must<HTMLElement>(document, '#libraryList');
    this.#tabs = [...this.#panel.querySelectorAll<HTMLButtonElement>('[data-tab]')];

    this.#searchRow = must<HTMLElement>(document, '#librarySearchRow');
    this.#searchInput = must<HTMLInputElement>(document, '#librarySearchInput');

    for (const button of this.#tabs) {
      button.addEventListener('click', () => {
        const tab = button.dataset.tab;
        if (isTab(tab)) this.#show({ kind: 'tab', tab });
      });
    }

    const runSearch = (): void => {
      const query = this.#searchInput.value.trim();
      // An empty search would spend 100 units of the daily budget to find nothing.
      if (query === '') return;
      this.#show({ kind: 'search', tab: 'search', query });
    };
    must<HTMLButtonElement>(document, '#librarySearchGo').addEventListener('click', runSearch);
    this.#searchInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') runSearch();
    });

    this.#back.addEventListener('click', () => {
      this.#show({ kind: 'tab', tab: this.#view.tab });
    });
    must<HTMLButtonElement>(document, '#libraryClose').addEventListener('click', () => {
      this.close();
    });
  }

  get isOpen(): boolean {
    return !this.#panel.hidden;
  }

  open(): void {
    this.#panel.hidden = false;
    this.#show({ kind: 'tab', tab: 'playlists' });
  }

  close(): void {
    this.#panel.hidden = true;
  }

  #show(view: View): void {
    this.#view = view;
    this.#requestId += 1;
    const requestId = this.#requestId;

    this.#back.hidden = view.kind === 'tab';
    this.#title.textContent = describeView(view);
    this.#searchRow.hidden = view.tab !== 'search';
    for (const button of this.#tabs) {
      button.setAttribute('aria-pressed', String(button.dataset.tab === view.tab));
    }

    this.#list.replaceChildren();
    this.#note.textContent = '読み込み中…';

    void this.#load(view)
      .then((items) => {
        if (requestId !== this.#requestId) return;
        this.#paint(view, items);
      })
      .catch((error: unknown) => {
        if (requestId !== this.#requestId) return;
        this.#note.textContent = describeFailure(error);
      });
  }

  async #load(view: View): Promise<LibraryItem[]> {
    // The search tab with nothing typed yet asks YouTube nothing at all — no token, no quota.
    if (view.kind === 'tab' && view.tab === 'search') return [];

    const token = this.#auth.currentToken() ?? (await this.#auth.trySilent());
    if (token === null) throw new YouTubeApiError(401, 'no token');

    if (view.kind === 'playlist') return fetchPlaylistItems(token, view.item.id);
    if (view.kind === 'channel') return fetchChannelVideos(token, view.item.id);
    if (view.kind === 'search') return searchVideos(token, view.query);
    if (view.tab === 'playlists') return fetchPlaylists(token);
    if (view.tab === 'subscriptions') return fetchSubscriptions(token);
    return fetchLikedVideos(token);
  }

  #paint(view: View, items: LibraryItem[]): void {
    if (items.length === 0) {
      this.#note.textContent = describeEmpty(view);
      return;
    }

    this.#note.textContent = '';
    const holdsVideos = view.kind !== 'tab' || view.tab === 'liked';
    const rows = items.map((item) =>
      holdsVideos ? this.#videoRow(item) : this.#folderRow(view, item),
    );
    // Twenty slots filled one tap at a time is twenty taps; this is one.
    if (holdsVideos && items.length > 1) rows.unshift(this.#fillAllRow(items));
    this.#list.replaceChildren(...rows);
  }

  /** Pours this list into the wall from the top, opening the wall if it is not showing. */
  #fillAllRow(items: readonly LibraryItem[]): HTMLElement {
    const row = document.createElement('li');
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'library-fill';
    button.textContent = `⬇ 上から順に ${Math.min(items.length, MAX_SLOTS)} 枠へ入れる`;
    button.addEventListener('click', () => {
      this.#callbacks.onFillAll(items.map((item) => item.id));
    });
    row.append(button);
    return row;
  }

  /** A row that opens something: a playlist or a channel. The whole row is the button. */
  #folderRow(view: View, item: LibraryItem): HTMLElement {
    const row = document.createElement('li');
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'library-row';
    button.append(this.#thumbnail(item), this.#label(item.title));
    button.addEventListener('click', () => {
      const kind = view.kind === 'tab' && view.tab === 'subscriptions' ? 'channel' : 'playlist';
      this.#show({ kind, tab: view.tab, item });
    });
    row.append(button);
    return row;
  }

  /** A row that is a video: one tap decides which slot receives it. */
  #videoRow(item: LibraryItem): HTMLElement {
    const row = document.createElement('li');
    const body = document.createElement('div');
    body.className = 'library-row';
    body.append(this.#thumbnail(item), this.#label(item.title));

    const targets: readonly (readonly [PickTarget, string])[] =
      this.#callbacks.layout() === 'wall'
        ? [['next', '選んだ枠へ']]
        : [
            ['video', '動画へ'],
            ['music', '音楽へ'],
          ];

    const actions = document.createElement('div');
    actions.className = 'library-actions';
    for (const [target, label] of targets) {
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = label;
      button.addEventListener('click', () => {
        this.#callbacks.onPick(item.id, target);
      });
      actions.append(button);
    }

    row.append(body, actions);
    return row;
  }

  #thumbnail(item: LibraryItem): HTMLElement {
    const image = document.createElement('img');
    image.className = 'library-thumb';
    image.loading = 'lazy';
    image.alt = '';
    if (item.thumbnail !== null) image.src = item.thumbnail;
    return image;
  }

  #label(title: string): HTMLElement {
    const span = document.createElement('span');
    span.className = 'library-title';
    span.textContent = title;
    return span;
  }
}
