/**
 * Turning touches on the full-screen picture into commands.
 *
 * The YouTube frame swallows every touch that lands on it, so the gestures live on a
 * transparent sheet laid over the top. That sheet only exists while a slot is full screen;
 * the rest of the time the frame belongs to YouTube, controls and all.
 *
 * All the arithmetic is in `gesture-math.ts` and tested there. What is left here is the
 * bookkeeping that cannot be tested without a browser: which fingers are down, whether a run
 * of taps has finished, and where the current drag started.
 */

import {
  classifyDrag,
  pinchIntent,
  seekSecondsFor,
  sideOf,
  speedStepsFor,
  volumeFor,
} from './gesture-math.js';

/**
 * How long a run of taps stays open for another one.
 *
 * Nothing waits this long to happen: the first tap plays or pauses straight away, and a
 * second tap takes that back before jumping. Waiting first would put this delay on every
 * single tap, which is the whole of what a slow picture feels like.
 */
const TAP_WINDOW_MS = 320;

export interface GestureHandlers {
  /** A single tap: play or pause. Acted on the moment the finger lifts. */
  readonly onToggle: () => void;
  /** Put back what the last `onToggle` did, because the tap turned out to be the first of several. */
  readonly onUndoToggle: () => void;
  /** A run of taps: jump by this many seconds, negative for backwards. */
  readonly onSeek: (seconds: number) => void;
  /** A sideways drag, in whole speed steps since the drag began. */
  readonly onSpeedStep: (steps: number) => void;
  /** An upward or downward drag. Called with the volume the finger is currently pointing at. */
  readonly onVolume: (volume: number) => void;
  /** A squeeze or a spread. */
  readonly onFit: (mode: 'fill' | 'fit') => void;
  /** Two fingers tapped at once. */
  readonly onTwoFingerTap: () => void;
  /** The volume to start a vertical drag from, read at the moment the finger lands. */
  readonly currentVolume: () => number;
}

interface Point {
  readonly x: number;
  readonly y: number;
}

function distance(a: Point, b: Point): number {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

/**
 * Pointer capture keeps a drag alive when the finger wanders off the picture, but it throws
 * for a pointer the browser no longer considers down. Losing capture costs a long drag;
 * letting the error out would cost the gesture entirely.
 */
function capture(sheet: HTMLElement, pointerId: number, hold: boolean): void {
  try {
    if (hold) sheet.setPointerCapture(pointerId);
    else if (sheet.hasPointerCapture(pointerId)) sheet.releasePointerCapture(pointerId);
  } catch {
    // Nothing to do: the gesture still works, it just ends if the finger leaves.
  }
}

/**
 * Starts listening. Returns the function that stops again — the sheet outlives any one
 * full-screen session, so the listeners have to come off with it.
 */
export function attachGestures(sheet: HTMLElement, handlers: GestureHandlers): () => void {
  const active = new Map<number, Point>();

  let startedAt: Point | null = null;
  let startVolume = 0;
  let steppedBy = 0;
  let dragged = false;
  let pinchStart = 0;
  /** Set once two fingers have been down together, so the lift is not read as a tap. */
  let multiTouch = false;
  /**
   * Set once a squeeze or spread has been acted on. Without it the lift looks like a
   * two-finger tap: acting on a pinch moves the baseline to wherever the fingers are, so by
   * the time they come up the distance matches the baseline exactly.
   */
  let pinched = false;

  let taps = 0;
  let tapSide: 'left' | 'right' = 'right';
  let tapTimer: number | null = null;

  /** True while the first tap's play-or-pause is still waiting to be taken back. */
  let toggleStands = false;

  const settleTaps = (): void => {
    tapTimer = null;
    const counted = taps;
    const side = tapSide;
    taps = 0;
    toggleStands = false;
    // One tap has already played or paused; only a run of them is left to act on.
    if (counted < 2) return;
    const seconds = seekSecondsFor(counted, side);
    if (seconds !== 0) handlers.onSeek(seconds);
  };

  const countTap = (point: Point): void => {
    tapSide = sideOf(point.x - sheet.getBoundingClientRect().left, sheet.clientWidth);
    taps += 1;
    if (taps === 1) {
      handlers.onToggle();
      toggleStands = true;
    } else if (toggleStands) {
      handlers.onUndoToggle();
      toggleStands = false;
    }
    if (tapTimer !== null) window.clearTimeout(tapTimer);
    tapTimer = window.setTimeout(settleTaps, TAP_WINDOW_MS);
  };

  const onDown = (event: PointerEvent): void => {
    capture(sheet, event.pointerId, true);
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });

    if (active.size === 1) {
      startedAt = { x: event.clientX, y: event.clientY };
      startVolume = handlers.currentVolume();
      steppedBy = 0;
      dragged = false;
      multiTouch = false;
      pinched = false;
      return;
    }

    multiTouch = true;
    if (active.size === 2) {
      const [a, b] = [...active.values()];
      pinchStart = a && b ? distance(a, b) : 0;
      // A run of single taps is not what two fingers meant; drop whatever was counted.
      taps = 0;
      toggleStands = false;
      if (tapTimer !== null) {
        window.clearTimeout(tapTimer);
        tapTimer = null;
      }
    }
  };

  const onMove = (event: PointerEvent): void => {
    if (!active.has(event.pointerId)) return;
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });

    if (active.size >= 2) {
      const [a, b] = [...active.values()];
      if (a === undefined || b === undefined || pinchStart <= 0) return;
      const intent = pinchIntent(distance(a, b) / pinchStart);
      if (intent !== 'none') {
        pinched = true;
        handlers.onFit(intent);
        // Acting once per squeeze: reset the baseline so it does not fire every frame.
        pinchStart = distance(a, b);
      }
      return;
    }

    if (startedAt === null) return;
    const dx = event.clientX - startedAt.x;
    const dy = event.clientY - startedAt.y;
    const kind = classifyDrag(dx, dy);
    if (kind === 'none') return;
    dragged = true;

    if (kind === 'horizontal') {
      const steps = speedStepsFor(dx);
      if (steps !== steppedBy) {
        handlers.onSpeedStep(steps - steppedBy);
        steppedBy = steps;
      }
      return;
    }

    handlers.onVolume(volumeFor(startVolume, dy, sheet.clientHeight));
  };

  const onUp = (event: PointerEvent): void => {
    const point = active.get(event.pointerId);
    const wasTwo = active.size === 2;
    active.delete(event.pointerId);
    capture(sheet, event.pointerId, false);

    if (wasTwo && !dragged && !pinched && pinchStart > 0) {
      const [a, b] = [...active.values(), point];
      if (a !== undefined && b !== undefined && Math.abs(distance(a, b) - pinchStart) < 24) {
        handlers.onTwoFingerTap();
      }
    }

    if (active.size > 0) return;

    if (!dragged && !multiTouch && point !== undefined) countTap(point);
    startedAt = null;
    pinchStart = 0;
  };

  const onCancel = (event: PointerEvent): void => {
    active.delete(event.pointerId);
    if (active.size === 0) {
      startedAt = null;
      pinchStart = 0;
    }
  };

  sheet.addEventListener('pointerdown', onDown);
  sheet.addEventListener('pointermove', onMove);
  sheet.addEventListener('pointerup', onUp);
  sheet.addEventListener('pointercancel', onCancel);

  return () => {
    sheet.removeEventListener('pointerdown', onDown);
    sheet.removeEventListener('pointermove', onMove);
    sheet.removeEventListener('pointerup', onUp);
    sheet.removeEventListener('pointercancel', onCancel);
    if (tapTimer !== null) window.clearTimeout(tapTimer);
    active.clear();
  };
}
